package net.oceancanvas.mod.worldgen;
import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import it.unimi.dsi.fastutil.longs.LongOpenHashSet;import net.minecraft.core.SectionPos;import net.minecraft.world.level.ChunkPos;
final class OceanCanvasNativeLightProofRevisionsTest {
 private static LongOpenHashSet section(int x,int z){return new LongOpenHashSet(new long[]{SectionPos.asLong(x,5,z)});}private static LongOpenHashSet empty(){return new LongOpenHashSet();}
 @Test void nativePublicationInvalidatesBeforeActualMapSwapOrQueuedCallback(){Object source=new Object();try(var g=OceanCanvasNativeLightProofRevisions.watch(source,new long[]{ChunkPos.pack(0,0)})){long stamp=g.stamp();try(var p=OceanCanvasNativeLightProofRevisions.begin(source,section(0,0),empty())){assertFalse(g.unchanged(stamp));assertEquals(-1,g.stamp());}assertFalse(g.unchanged(stamp));assertTrue(g.unchanged(g.stamp()));}}
 @Test void unrelatedPublicationDoesNotRestartEarlierProofSlices(){Object source=new Object();try(var g=OceanCanvasNativeLightProofRevisions.watch(source,new long[]{ChunkPos.pack(0,0)})){long stamp=g.stamp();try(var p=OceanCanvasNativeLightProofRevisions.begin(source,section(30,40),empty())){assertFalse(g.unchanged(stamp));}assertTrue(g.unchanged(stamp));}}
 @Test void neighborAndAffectedOnlyUpdatesAreIncluded(){Object source=new Object();try(var g=OceanCanvasNativeLightProofRevisions.watch(source,new long[]{ChunkPos.pack(0,0),ChunkPos.pack(-1,0)})){long stamp=g.stamp();try(var p=OceanCanvasNativeLightProofRevisions.begin(source,empty(),section(-1,0))){}assertFalse(g.unchanged(stamp));}}
 @Test void sourceIsolationColdAndCloseRefuseOldCredit(){Object a=new Object(),b=new Object();var g=OceanCanvasNativeLightProofRevisions.watch(a,new long[]{0});long stamp=g.stamp();try(var p=OceanCanvasNativeLightProofRevisions.begin(b,section(0,0),empty())){}assertTrue(g.unchanged(stamp));g.close();assertFalse(g.unchanged(stamp));try(var cold=OceanCanvasNativeLightProofRevisions.watch(a,new long[]{0})){assertTrue(cold.unchanged(cold.stamp()));}}
 @Test void nestedAndExceptionalNativePublicationAlwaysBalance(){Object a=new Object();try(var g=OceanCanvasNativeLightProofRevisions.watch(a,new long[]{0})){try{try(var p=OceanCanvasNativeLightProofRevisions.begin(a,section(0,0),empty())){try(var q=OceanCanvasNativeLightProofRevisions.begin(a,empty(),empty())){assertEquals(-1,g.stamp());}throw new IllegalStateException("native failure");}}catch(IllegalStateException expected){}assertTrue(g.unchanged(g.stamp()));}}
 @Test void concurrentPublicationCannotValidatePriorStamp()throws Exception{Object a=new Object();try(var g=OceanCanvasNativeLightProofRevisions.watch(a,new long[]{0})){long stamp=g.stamp();Thread t=new Thread(()->{try(var p=OceanCanvasNativeLightProofRevisions.begin(a,section(0,0),empty())){}});t.start();t.join();assertFalse(g.unchanged(stamp));}}
 @Test void registrationDuringPreviouslyUnwatchedSwapCannotCreditPartialMap(){Object source=new Object();try(var p=OceanCanvasNativeLightProofRevisions.begin(source,section(0,0),empty())){try(var g=OceanCanvasNativeLightProofRevisions.watch(source,new long[]{0})){assertEquals(-1,g.stamp());assertFalse(g.unchanged(0));}}}
}
